window.DEFAULT_DECK_VERSION = 4; // cards_data.js を更新するたびに、この数値を1つ増やしてください
window.DEFAULT_CARDS = [{"id": "c0005", "name": "抜け止め形コンセント", "category": "コンセント", "tags": [], "difficulty": 2, "description": "受け口が「こ」の字形のコンセントです。プラグを差し込んでから右にひねると引っ張っても抜けにくくなります。主に天井付コンセントなどで見かけることがあります。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0001", "name": "接地極付コンセント", "category": "コンセント", "tags": [], "difficulty": 2, "description": "接地極が付いたコンセント。接地が必要な接地極付プラグの差込口に用います。洗濯機や電子レンジのコンセントには接地極付きコンセントもしくは接地極付接地端子付コンセントを使用することが規定されています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0003", "name": "接地端子付コンセント", "category": "コンセント", "tags": [], "difficulty": 2, "description": "接地線を接続するための接地端子が付いたコンセントです。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0002", "name": "接地極付接地端子付コンセント", "category": "コンセント", "tags": [], "difficulty": 2, "description": "接地線を接続する接地端子と接地極の両方を持つコンセントです。洗濯機や電子レンジのコンセントには接地極付きコンセントもしくは接地極付接地端子付コンセントを使用することが規定されています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0004", "name": "防雨形コンセント", "category": "コンセント", "tags": [], "difficulty": 2, "description": "屋外の雨水がかかる場所に取り付けるコンセントです。雨水がかからないようにフードがついています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0006", "name": "接地極付コンセント（三相200V）", "category": "コンセント", "tags": [], "difficulty": 2, "description": "三相200V用の接地極付コンセント。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0007", "name": "確認表示灯内蔵スイッチ", "category": "スイッチ", "tags": [], "difficulty": 2, "description": "スイッチが「入」の状態になると表示灯が点灯します。そのため、スイッチが入っていること=機械が動作していることを容易に確認することができます。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0008", "name": "位置表示灯内蔵スイッチ", "category": "スイッチ", "tags": [], "difficulty": 2, "description": "スイッチが「切」の状態になると表示灯が点灯します。そのため、照明が点灯していない暗闇でも位置表示灯内蔵スイッチの表示灯が点灯し、スイッチの位置を容易に確認することができます。別名「ほたるスイッチ」とも呼ばれています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0024", "name": "2極スイッチ", "category": "スイッチ", "tags": [], "difficulty": 2, "description": "2つの電路を同時に制御できるスイッチです。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0009", "name": "3路スイッチ", "category": "スイッチ", "tags": ["複線図"], "difficulty": 2, "description": "二ヶ所から照明の点滅を行うためのスイッチ。外観はなにも特徴が無く4路スイッチと似ています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0017", "name": "配線用遮断器", "category": "配線用遮断器など", "tags": ["材料及び工具"], "difficulty": 2, "description": "過電流遮断器の一種で、回路の許容値を超える電流が流れた際に自動的に電路を遮断する保護装置です。過電定格電流の1.0倍の電流では動作してはなりません。30A以下の定格電流の場合、1.25倍の電流で60分以内、定格電流の2倍の電流で2分以内の溶断時間が求められます。また、30Aを超え50A以下の定格電流の場合、1.25倍の電流で60分以内、定格電流の2倍で4分以内の溶断時間が求められます。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0016", "name": "配線用遮断器(電動機保護機能付)モータブレーカ", "category": "配線用遮断器など", "tags": ["材料及び工具"], "difficulty": 2, "description": "電動機兼用のブレーカーです。電動機が過負荷運転したり、配線が短絡したりすると自動的に遮断します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0015", "name": "漏電遮断器", "category": "配線用遮断器など", "tags": [], "difficulty": 2, "description": "漏電が発生した際にのみ自動的に電路を遮断する器具です。過負荷保護が付いていない漏電遮断器は過電流を遮断することはできません。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0014", "name": "漏電遮断器（過負荷保護付）", "category": "配線用遮断器など", "tags": [], "difficulty": 2, "description": "漏電・過電流が発生した際、自動的に電路を遮断する器具。過負荷保護付の漏電遮断器は漏電だけでなく過電流が発生した際にも電路を遮断することが可能です。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0013", "name": "電磁開閉器", "category": "配線用遮断器など", "tags": ["材料及び工具"], "difficulty": 2, "description": "電動機の遠隔操作や自動操作に使われる。電磁石で電路のオン・オフを行う開閉器です。上部の電磁接触器と下部のサーマルリレーで構成されています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0012", "name": "コンデンサ", "category": "配線用遮断器など", "tags": ["材料及び工具"], "difficulty": 2, "description": "電動機などの力率を改善するために用いられる。低圧用には静電容量がマイクロ・ファラド(μF)で表示される。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_小型変圧器トランス_95", "name": "小型変圧器(トランス)", "category": "配線用遮断器など", "tags": [], "difficulty": 2, "description": "電圧を変える器具。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0010", "name": "4路スイッチ", "category": "スイッチ", "tags": ["複線図"], "difficulty": 2, "description": "3ヶ所以上の場所から照明の点滅を行うためのスイッチで3路スイッチと組み合わせて使用します。基本的に4路スイッチ単独で使用することはありません。外観はなにも表示がなく3路スイッチと似ています。第二種電気工事士技能試験でも登場します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0018", "name": "タイムスイッチ", "category": "スイッチ", "tags": ["材料及び工具"], "difficulty": 2, "description": "設定した時間に電路を開閉するスイッチです。タイマーが付いているのが特徴です。特定電気用品に該当します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0019", "name": "調光器", "category": "スイッチ", "tags": ["材料及び工具"], "difficulty": 2, "description": "照明器具の明るさを連続的または段階的に調整する装置です。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0021", "name": "電磁開閉器用押しボタン", "category": "スイッチ", "tags": ["材料及び工具"], "difficulty": 2, "description": "電磁開閉器のオン・オフの操作に使用します。確認表示灯が内蔵される時は傍記表示にLがつき、ボタンの上にパイロットランプがつきます。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0022", "name": "プルスイッチ", "category": "スイッチ", "tags": ["材料及び工具"], "difficulty": 2, "description": "壁に取り付けてひもを引く(PULL)ことで操作するスイッチです。照明器具の点滅に用いられることが多いです。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0023", "name": "自動点滅器", "category": "スイッチ", "tags": ["材料及び工具"], "difficulty": 2, "description": "光を感知するセンサが内蔵されており暗くなると照明を点灯するスイッチです。センサ受光部が半透明のカバーで覆われているのが外観の特徴です。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_圧力スイッチ_90", "name": "圧力スイッチ", "category": "スイッチ", "tags": [], "difficulty": 2, "description": "設定した圧力になった時にスイッチが動作。\n水圧、油圧、空気圧などの圧力制御に使われる。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0026", "name": "白熱灯（壁付）", "category": "照明器具", "tags": ["材料及び工具"], "difficulty": 2, "description": "白熱電球を光源に使う照明器具で壁に取り付けて使用します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0027", "name": "蛍光灯（壁付）", "category": "照明器具", "tags": [], "difficulty": 2, "description": "蛍光灯の主な特徴は次の通りです。・発光効率が高い・寿命が長い・グローランプによる雑音がある・力率が悪い・使用するには安定器が必要。壁に取り付ける際の配線図記号は壁面を黒く塗ります。もしくは傍記表示でWallのWを表記します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0083", "name": "ペンダント", "category": "照明器具", "tags": [], "difficulty": 2, "description": "天井から吊り下げるタイプの照明器具です。天井に取り付けられた引掛シーリングがあれば簡単に設置でき、デザイン性に富んだものが多いです。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0038", "name": "ねじなし電線管", "category": "電線菅", "tags": [], "difficulty": 2, "description": "金属管で可とう性(曲げられる)がないもの。\n管の厚みが1.2mm以上の金属製電線管で、ねじが切られていないものを差します。配線図上ではE(19)と、E(外径の値)で表します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0035", "name": "ねじなし管用カップリング", "category": "電線菅", "tags": [], "difficulty": 2, "description": "ねじなし電線管相互の接続する際に使用します。止めねじが付いているのが特徴で、この止めねじでねじなし電線管を固定します。\n【使用可否】\nねじなし電線菅○\n薄鋼電線菅×", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_薄鋼電線菅_99", "name": "薄鋼電線菅", "category": "電線菅", "tags": [], "difficulty": 2, "description": "金属管で可とう性(曲げられる)がないもの。\n管の厚みが1.2mm以上の金属製電線管で、ねじが切られているものを差します。配線図上ではE(19)と、E(外径の値)で表します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0036", "name": "カップリング", "category": "電線菅", "tags": [], "difficulty": 2, "description": "薄鋼電線管相互を接続する際に使用します。\nカップリングの内側にねじが切られているため、ねじが切られている薄鋼電線管しか接続することができません。\n\n【使用可否】\nねじなし電線菅×\n薄鋼電線菅○", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0037", "name": "金属製可とう電線管(プリカチューブ)", "category": "電線菅", "tags": [], "difficulty": 2, "description": "金属菅の中で可とう性(曲げることができる)があるもの。\n表面がジャバラになっている。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0034", "name": "コンビネーションカップリング", "category": "電線菅", "tags": [], "difficulty": 2, "description": "2種金属製可とう電線管と金属管を接続するために使用します。金属管がねじなし電線管である場合は、ビス止めタイプのものを使用します。\n【使用可否】\nねじなし電線菅○\n薄鋼電線菅○", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0032", "name": "ノーマルベンド", "category": "電線菅", "tags": [], "difficulty": 2, "description": "電線菅をカーブさせるように接続したい場合に使う。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0033", "name": "ユニバーサル", "category": "電線菅", "tags": [], "difficulty": 2, "description": "露出金属管工事で、金属管相互を直角に接続する場所に使用します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0031", "name": "硬質塩化ビニル電線管(VE菅)", "category": "電線菅", "tags": [], "difficulty": 2, "description": "合成樹脂管の中で可とう性(曲げられる)が無いもの。\nVE管とも呼ばれます。屋内配線工事においては全ての場所で施工可能です。配線図上で表記する際はVEと内径の太さを記載します。TSカップリングを使用してVE管を相互接続する際の差込深さは指定があり、接着剤を使用しない場合は管外径の1.2倍以上・接着剤を使用する場合は管外径の0.8倍以上と定められています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0029", "name": "TSカップリング", "category": "電線菅", "tags": [], "difficulty": 2, "description": "合成樹脂菅の接続に使用。\n【使用可否】\nVE菅○\nPF菅×\n\nVE管相互を接続する際に使用します。TSカップリングなどでVE管を相互接続する際は差込深さが定められています。接着剤を使用しない場合はVE管外径の1.2倍以上、接着剤を使用する場合はVE管外径の0.8倍以上差し込む必要があります。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0030", "name": "PF管", "category": "電線菅", "tags": [], "difficulty": 2, "description": "合成樹脂製可とう電線管の中で可とう性があり、自己消化性があるもの。\n衝撃性は弱いですが、自己消化性があり、絶縁性も高いため全ての屋内配線工事で使用できます。配線図上ではPF(16)と、PF(内径の値)で表します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_CD菅_100", "name": "CD菅", "category": "電線菅", "tags": [], "difficulty": 2, "description": "合成樹脂製可とう電線管の中で、可とう性(曲げられる)があり、自己消化性が無いもの。\nオレンジ色で自己消火性はなくコンクリート埋め込み用に使用します。そのため、屋内配線では使用しません。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0028", "name": "PF管用カップリング", "category": "電線菅", "tags": [], "difficulty": 2, "description": "合成樹脂菅の接続に使用。\n【使用可否】\nVE菅×\nPF菅○\n\nPF管同士を接続する材料です。PF管の差込口が両側に付いています。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0039", "name": "ケーブルラック", "category": "電線菅", "tags": ["材料及び工具"], "difficulty": 2, "description": "ケーブル工事でケーブルを支持・固定するためのラックです。ビル内や駅構内などでよく見かけます。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0042", "name": "アウトレットボックス", "category": "ボックス", "tags": ["材料及び工具"], "difficulty": 2, "description": "電線相互をリングスリーブや差込形コネクタで接続する際に、接続点をアウトレットボックス内に収めます。そうすることで電線の引き入れや点検を容易にすることができます。外観の特徴としては打ち抜き穴があり、ゴムブッシングやボックスコネクタを取り付けて使用します。金属製と合成樹脂製のものがあります。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0043", "name": "VVF用ジョイントボックス", "category": "ボックス", "tags": ["材料及び工具"], "difficulty": 2, "description": "隠ぺい場所でVVFケーブル同士を接続する際に用いる透明なカバーです。技能試験の単線図にも記載がありますが、試験では使用を省略されます。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0044", "name": "コンクリートボックス", "category": "ボックス", "tags": ["材料及び工具"], "difficulty": 2, "description": "コンクリートに埋め込み、電線の接続、電灯やスイットの取り付けに使用します。底面部にフタがあり、コンクリート型枠取付用の突起があるのが特徴です。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0045", "name": "プルボックス", "category": "ボックス", "tags": [], "difficulty": 2, "description": "電線管工事やケーブル工事で電線の接続や引入れを行うのに使用します。プルボックスはJIS規格がないため様々なサイズが展開されています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0046", "name": "回路計", "category": "計測器", "tags": [], "difficulty": 2, "description": "直流の電圧・電流や、交流の電圧・抵抗などを測定することができます。(V・A・Ω)\n別名テスタとも言います。屋内配線の点検で使用する際は断線の有無や導通の確認を目的に使用します。デジタル式とアナログ式の2種類あります。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0047", "name": "絶縁抵抗計", "category": "計測器", "tags": [], "difficulty": 2, "description": "絶縁抵抗を測定する際に用いる計測器です。EとLの端子表示とMΩの表示が特徴です。メガーとも言います。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0048", "name": "接地抵抗計", "category": "計測器", "tags": [], "difficulty": 2, "description": "接地極と大地間の電気抵抗を測定するための計測器です。3色(緑・黄・赤)の接続用電線と補助接地棒があるのが特徴です。使用する際は接地極にE端子、それぞれ10m以上の間隔をあけてP端子、C端子の順に一直線上に補助接地棒に接続します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0049", "name": "検相器", "category": "計測器", "tags": [], "difficulty": 2, "description": "三相交流回路の相順(R/S/T相の順序)を調べる計測器です。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0050", "name": "検電器", "category": "計測器", "tags": [], "difficulty": 2, "description": "電路が充電されているかどうかを調べるチェッカーです。電圧を測定することはできません。電路が充電されている状態で施工を行うと感電する恐れがあるため、施工前に検電器で電路の充電の有無を確認します。ネオン式、音響発光式などの種類があります。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0051", "name": "照度計", "category": "計測器", "tags": [], "difficulty": 2, "description": "照度を測定する際に用いる計測器です。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_ペンチ_103", "name": "ペンチ", "category": "電線・ケーブルの工具", "tags": [], "difficulty": 2, "description": "電線・ケーブルを切断するのに使用。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0052", "name": "ケーブルカッター", "category": "電線・ケーブルの工具", "tags": [], "difficulty": 2, "description": "ケーブル切断用カッターです。刃先が電線をくわえ込むような形状をしています。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0053", "name": "電工ナイフ", "category": "電線・ケーブルの工具", "tags": [], "difficulty": 2, "description": "電線のケーブル外装や芯線被覆のストリップを行う際に用いる工具です。技能試験の指定工具にも含まれており、ケーブル外装のストリップ以外にもゴムブッシングの施工にも使用します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0054", "name": "ケーブルストリッパー", "category": "電線・ケーブルの工具", "tags": [], "difficulty": 2, "description": "ビニル外装(シース)や絶縁被覆を剥ぎ取る際に使用します。ワイヤーストリッパーとも呼ばれます。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0055", "name": "ワイヤーストリッパー", "category": "電線・ケーブルの工具", "tags": [], "difficulty": 2, "description": "絶縁電線の被覆のはぎ取りに使用します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0057", "name": "金切りのこ", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "金属管を切断する際に使用。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0058", "name": "パイプカッタ", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "金属管の切断に使用する工具。\n金属管をカッタのローラと刃ではさみ、\nハンドルを回転させながら切断。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0066", "name": "リード型ねじ切り器", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "金属管のねじ切りに使用します。\nダイスと呼ばれる刃が組み込まれており、ねじ切りを行う際は必ず油差しで油を注ぎながら行いましょう。\n※ねじなし電線管は薄いためねじ切り加工はできません。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0059", "name": "パイプバイス", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "金属管の固定に使用。\n電線管の切断やねじ切りを行う際に管の固定する。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0060", "name": "パイプレンチ", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "金属管とカップリングを接続する際の固定や締め付けに使用する工具。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0067", "name": "パイプベンダ", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "金属管を曲げる際に使用する工具です。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_金やすり_105", "name": "金やすり", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "切断面のバリ取りに使用。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0061", "name": "ウォーターポンププライヤー", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "パイプレンチと同じ用途。\n工具の厚さは薄いのでボックスコネクタのロックナットの締め付けなどにも使用。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0062", "name": "ホルソ", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "電動ドリルに取り付けて、金属板に穴をあける際に用います。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0063", "name": "ノックアウトパンチャ", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "レバーを動かすことで金属板に穴を開けることが可能。\nプルボックスなどの鋼板に穴を開けに使用。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0064", "name": "リーマ", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "金属管の内面のバリ取りに使用します。\nクリックボールの先端に取り付けて使用します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0068", "name": "合成樹脂管用カッタ", "category": "合成樹脂菅工具", "tags": [], "difficulty": 2, "description": "合成樹脂管である硬質塩化ビニル管を切断する工具。\nPF管やCD管の合成樹脂製可とう電線管の切断には樹脂フレキシブル管カッタを使用します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0069", "name": "面取り器", "category": "合成樹脂菅工具", "tags": [], "difficulty": 2, "description": "VE管のバリ取りに使用する工具です。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0070", "name": "トーチランプ", "category": "合成樹脂菅工具", "tags": [], "difficulty": 2, "description": "硬質塩化ビニル電線管(VE管)を曲げるために管を熱する際に用いる工具です。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0071", "name": "羽根ぎり", "category": "木材工具", "tags": [], "difficulty": 2, "description": "木材に穴を開ける際に用いる工具。\nクリックボールに取り付けて使用します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0072", "name": "木工用ドリル", "category": "木材工具", "tags": [], "difficulty": 2, "description": "電動ドリルやクリックボールに取り付けて、木材に穴をあける際に用います。\n金属用のドリルと比較して先端がより鋭利なのが特徴です。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0073", "name": "絶縁ブッシング", "category": "その他工具", "tags": [], "difficulty": 2, "description": "金属管の管端部やボックスコネクタに取り付け電線被覆の保護に使用します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0074", "name": "サドル", "category": "その他工具", "tags": [], "difficulty": 2, "description": "電線管を造営材に固定する時に用いる。金属管には金属製、合成樹脂管には合成樹脂製のサドルを使用します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0075", "name": "ステップル(ステープル)", "category": "その他工具", "tags": [], "difficulty": 2, "description": "VVFケーブルを木製の造営材に固定する際に使用します。先端が尖っており、ハンマ(金づち)で叩き込んでケーブルを固定します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0076", "name": "張線器", "category": "その他工具", "tags": [], "difficulty": 2, "description": "電線やメッセンジャワイヤのたるみの調整に使う工具です。シメラとも言います。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0077", "name": "IV線　(600V絶縁ビニル電線)", "category": "電線・ケーブル", "tags": [], "difficulty": 2, "description": "600Vビニル絶縁電線のことを示します。配線図上で表す際、Indoor Vinylのイニシャルを取ってIVと表記されます。屋内配線でのみ使用され、ケーブルと違って外装被覆がないため、配線する際は金属管やPF管などの電線管で保護する必要があります。最高許容温度は60℃とVVFケーブル・VVRケーブルと同じです。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0078", "name": "VVF線　(600Vビニル絶縁ビニルシースケーブル)", "category": "電線・ケーブル", "tags": [], "difficulty": 2, "description": "600Vビニル絶縁ビニル外装ケーブル平型のことを示します。配線図上で表す際、Vinyl insulated Vinyl sheathed Flat-type cableのイニシャルを取ってVVFと表記されます。屋内・屋外・地中配線で使用され、第二種電気工事士技能試験でもメインのケーブルとして使用されます。最高許容温度は60℃とVVRケーブルと同じです。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0079", "name": "VVR線　(600Vビニル絶縁ビニルシースケーブル)", "category": "電線・ケーブル", "tags": [], "difficulty": 2, "description": "600Vビニル絶縁ビニル外装ケーブル丸型のことを示します。配線図上で表す際、Vinyl insulated Vinyl sheathed Round-type cableのイニシャルを取ってVVRと表記されます。屋内・屋外・地中配線・引込口で使用され、外装被覆と芯線被覆の間にケーブルを丸く仕上げるための介在物と呼ばれる紙ひものような詰め物がされています。最高許容温度は60℃とVVFケーブルと同じです。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0080", "name": "EM-EEFケーブル　(600Vポリエチレン絶縁耐燃性ポリエチレン)", "category": "電線・ケーブル", "tags": [], "difficulty": 2, "description": "600Vポリエチレン絶縁耐燃性ポリエチレン外装ケーブル平型のことを示します。配線図上で表す際、Eco Material polyEthylene insulated poliyEthylene sheathed Flat-type cableから取ってEM-EEFと表記されます。屋内配線、屋外配線、地中配線で使用できます。VVFケーブルと似ていますが、EM-EEFケーブルは被覆の素材が難燃性で環境に配慮した素材を使用しているという違いがあります。最高許容温度は75℃です。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0081", "name": "換気扇（天井付）", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "室内の空気の排出・排煙や室外の空気との換気を行います。壁付と天井付で記号が異なり、天井付の場合は四角枠の記号で表します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0082", "name": "換気扇（壁付）", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "室内の空気の排出・排煙や室外の空気との換気を行います。壁付と天井付で記号が異なり、壁付の場合は丸枠の記号で表します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0084", "name": "シャンデリア", "category": "照明器具", "tags": [], "difficulty": 2, "description": "複数の光源をもつ、ガラスや金属などで華やかに装飾された照明器具です。天井に取り付けて使用します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0085", "name": "ダウンライト", "category": "照明器具", "tags": [], "difficulty": 2, "description": "天井に埋め込んで使用する照明器具です。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0025", "name": "水銀灯", "category": "照明器具", "tags": ["材料及び工具"], "difficulty": 2, "description": "青白い発光色で道路や公園などの照明に多く利用されます。発光効率が高く、寿命が長いのが特徴です。水銀灯の使用には安定器が必須です。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_引掛形コンセント_87", "name": "引掛形コンセント", "category": "コンセント", "tags": [], "difficulty": 2, "description": "", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_医用コンセント_86", "name": "医用コンセント", "category": "コンセント", "tags": [], "difficulty": 2, "description": "", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_屋外ユニット_88", "name": "屋外ユニット", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_屋内ユニット_89", "name": "屋内ユニット", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_握り押しボタンスイッチ_91", "name": "握り押しボタンスイッチ", "category": "スイッチ", "tags": [], "difficulty": 2, "description": "握ってボタンを押すことでボタンのオンオフを操作できる。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_フロートスイッチ_92", "name": "フロートスイッチ", "category": "スイッチ", "tags": [], "difficulty": 2, "description": "ボールの部分を液体に浮かべる。\n液体に浮かぶボールの高さによってオンオフを動作する。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0020", "name": "フロートレススイッチ電極", "category": "スイッチ", "tags": [], "difficulty": 2, "description": "給排水の水位を検知する器具です。ポンプの動作等に用いられます。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_ナトリウム灯_93", "name": "ナトリウム灯", "category": "照明器具", "tags": [], "difficulty": 2, "description": "", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_メタルハライド灯_94", "name": "メタルハライド灯", "category": "照明器具", "tags": [], "difficulty": 2, "description": "メタルハライドランプは白・青味がかかったものが多く、演色性にこだわる場面などに使われています。\n球場のナイター用の照明や、アクアリウム等で見ることが出来ます。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0011", "name": "電力量計", "category": "配線用遮断器など", "tags": ["材料及び工具"], "difficulty": 2, "description": "電力量を測定するのに用います。消費された電力に応じ計器の中の円盤が回り、回転数を積算して消費された電力を表します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_電力計_96", "name": "電力計", "category": "配線用遮断器など", "tags": [], "difficulty": 2, "description": "電力を測る器具。ワットの記載がある。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_電流計_97", "name": "電流計", "category": "配線用遮断器など", "tags": [], "difficulty": 2, "description": "電流を測る器具。アンペアの表記がある。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_電圧計_98", "name": "電圧計", "category": "配線用遮断器など", "tags": [], "difficulty": 2, "description": "電圧を測るための器具。ボルトの記載がある。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0040", "name": "金属線ぴ", "category": "電線菅", "tags": [], "difficulty": 2, "description": "線ぴ(線樋)は配線を収めるモールで、金属製のものを金属線ぴと言います。金属線ぴには1種と2種があり1種金属線ぴは幅が4cm未満、2種は幅が4cm以上5cm以下と幅で種類が分けられます。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0041", "name": "ライティングダクト", "category": "電線菅", "tags": ["材料及び工具"], "difficulty": 2, "description": "店舗の天井などに取り付けて使用します。樋の中に導体が組み込まれているダクトです。照明器具やコンセントを任意の位置に取り付けることが出来ます。開口部は下に向けて使用します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_金属ダクト_101", "name": "金属ダクト", "category": "電線菅", "tags": [], "difficulty": 2, "description": "金属製のダクト。主に工場やビルなど大きな施設で使われる。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_漏れ電流計_102", "name": "漏れ電流計", "category": "計測器", "tags": [], "difficulty": 2, "description": "洗濯バサミなような部分に電線を挟んで漏れ電流を測る。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0056", "name": "リングスリーブ", "category": "電線・ケーブルの工具", "tags": ["複線図"], "difficulty": 2, "description": "電線の圧着接続に使用します。リングスリーブのサイズは小、中、大があり、ハンドル部が黄色のリングスリーブ用圧着工具で圧着を行います。圧着時は接続する電線の太さ・本数によって適切なリングスリーブのサイズ・圧着工具の圧着ダイスが定められています。技能試験で出題される際は絶縁処理は省略されますが、実際の電気工事では接続後の絶縁処理が必要です。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_裸圧着端子_104", "name": "裸圧着端子", "category": "電線・ケーブルの工具", "tags": [], "difficulty": 2, "description": "一本の電線に圧着する際に使用する。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "c0065", "name": "クリックボール", "category": "金属管工具", "tags": [], "difficulty": 2, "description": "クリックボールの先端にリーマや羽根ぎりを取り付けて使用します。リーマは金属管の面取りに使用します。羽根ぎりは木材の穴あけに使用します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_ロックナット_106", "name": "ロックナット", "category": "その他工具", "tags": [], "difficulty": 2, "description": "", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_リングレジューサ_107", "name": "リングレジューサ", "category": "その他工具", "tags": [], "difficulty": 2, "description": "", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_合成樹脂製埋込形スイッチ_108", "name": "合成樹脂製埋込形スイッチボックス", "category": "ボックス", "tags": [], "difficulty": 2, "description": "", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_安定器_109", "name": "安定器", "category": "その他工具", "tags": [], "difficulty": 2, "description": "", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_天井隠ぺい配線_111", "name": "天井隠ぺい配線", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "天井内部の見えないところに施工された配線のことを示します。配線図上で実線で描かれているものは天井隠ぺい配線となります。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_床隠ぺい配線_112", "name": "床隠ぺい配線", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "フロアダクト工事などの床下に施工された配線のことを示します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_地中埋設配線_110", "name": "地中埋設配線", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "地中に埋設された配線です。\n直接埋設式や暗きょ式、管路式などの方法があります。\n使用する電線はケーブルでなければならず、絶縁電線は使用できません。\n駐車場など重量物の圧力を受ける場所はトラフなどを使用して1.2ｍ以上の深さまで埋設し、歩行路など圧力を受けない場所は堅ろうな板などで覆って0.6ｍ以上の深さまで埋設します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}, {"id": "card_露出配線_113", "name": "露出配線", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "天井や床内に配線を収めるのではなく、壁や柱などの造営材に固定して外から見る場所に配線されたものを指します。", "symbolImage": false, "photoImage": true, "createdAt": "2026-08-17T00:00:00.000Z", "updatedAt": "2026-08-17T00:00:00.000Z"}];
